from datetime import timedelta
import unittest

import config
import database
import friends
import models
import recommender
import support


def profile(user_id=1, direction='career'):
    """Create a fixed domain profile with no favorites for scoring comparisons."""
    return models.UserProfile(user_id, 'Alex', 'ALEX23', {direction})


class FeatureTests(unittest.TestCase):
    """Verify explicit feature values, binary labels, column alignment and learned scoring."""

    def test_labels_and_invalid_values(self):
        """Label ratings 4–5 positively and reject missing, boolean or fractional ratings."""
        self.assertEqual([recommender.make_label(value) for value in range(1, 6)], [0, 0, 0, 1, 1])
        for invalid in (None, True, 0, 6, 4.0, '4'):
            with self.assertRaises(ValueError):
                recommender.make_label(invalid)

    def test_feature_values_and_no_identifiers(self):
        """Encode time, money and preferences without using event/user IDs as model features."""
        event = support.event(start=support.NOW.replace(hour=12, minute=30),
                              end=support.NOW.replace(hour=14), price='25.50', club_id=3)
        person = models.UserProfile(1, 'Alex', 'ALEX23', {'career'}, {1}, {3}, {'career_tech'})
        row = recommender.event_feature_row(event, person, 2, 4.5)
        self.assertEqual(set(row), set(config.ML_FEATURE_COLUMNS))
        self.assertEqual(row['time_of_day'], 'afternoon')
        self.assertAlmostEqual(row['start_hour'], 12.5)
        self.assertAlmostEqual(row['price_chf'], 25.5)
        self.assertEqual(row['duration_minutes'], 90)
        self.assertEqual(row['wants_direction'], 1)
        self.assertEqual((row['fav_series'], row['fav_club'], row['fav_bundle']), (1, 1, 1))
        self.assertEqual(str(event.price), '25.50')
        self.assertNotIn('event_id', row)
        self.assertNotIn('user_id', row)

    def test_time_boundaries_and_unknown_price(self):
        """Use noon and 17:00 boundaries while distinguishing free from unknown prices."""
        cases = [(11, 'morning'), (12, 'afternoon'), (16, 'afternoon'), (17, 'evening')]
        for hour, expected in cases:
            event = support.event(start=support.NOW.replace(hour=hour),
                                  end=support.NOW.replace(hour=hour + 1), price=None)
            row = recommender.event_feature_row(event, profile(), 0, config.NEUTRAL_RATING)
            self.assertEqual(row['time_of_day'], expected)
            self.assertEqual(row['is_free'], 0)
        event.price = '0'
        self.assertEqual(recommender.event_feature_row(event, profile(), 0, 3)['is_free'], 1)

    def test_unseen_category_alignment(self):
        """Ignore unseen one-hot columns and preserve every trained column in its original order."""
        row = recommender.event_feature_row(support.event(), profile(), 0, 3)
        trained = recommender.to_feature_matrix([row])
        unseen = row.copy()
        unseen['bundle'] = 'brand_new_bundle'
        unseen['unwanted_identifier'] = 12345
        scored = recommender.to_feature_matrix([unseen], list(trained.columns))
        self.assertEqual(list(scored.columns), list(trained.columns))
        self.assertEqual(scored.iloc[0]['bundle_career_tech'], 0)
        self.assertNotIn('unwanted_identifier', scored)
        self.assertFalse(scored.isna().any().any())
        empty = recommender.to_feature_matrix([], list(trained.columns))
        self.assertTrue(empty.empty)
        self.assertEqual(list(empty.columns), list(trained.columns))

    def test_training_fallback_and_validation(self):
        """Fall back for small/single-class datasets and reject mismatched inputs."""
        row = recommender.event_feature_row(support.event(), profile(), 0, 3)
        X = recommender.to_feature_matrix([row] * config.MIN_TRAINING_ROWS)
        self.assertIsNone(recommender.train_production_model(X, [1] * len(X), [1] * len(X)))
        self.assertIsNone(recommender.train_production_model(X.iloc[:2], [0, 1], [1, 1]))
        with self.assertRaises(ValueError):
            recommender.train_production_model(X, [0], [1])
        with self.assertRaises(ValueError):
            recommender.train_production_model(X.iloc[:2], [0, 1], [1, float('nan')])
        with self.assertRaises(ValueError):
            recommender.to_feature_matrix([{'direction': 'career'}])

    def test_forest_personalizes_top_three(self):
        """Learn the focus interaction and personalize the top three for two new profiles."""
        people = [profile(1, 'sports'), profile(2, 'career')]
        events = []
        for index in range(6):
            direction = 'sports' if index < 3 else 'career'
            bundle = 'sports_ball' if direction == 'sports' else 'career_tech'
            events.append(support.event(event_id=index + 1, direction_key=direction,
                                         bundle_key=bundle))
        rows, labels = [], []
        for repeat in range(50):
            for person in people:
                for event in events:
                    rows.append(recommender.event_feature_row(event, person, 0, 3))
                    labels.append(int(person.wants_direction(event)))
        X = recommender.to_feature_matrix(rows)
        model = recommender.train_production_model(X, labels, [1] * len(labels))
        scorer = recommender.Recommender(model, X.columns)
        self.assertEqual(model.n_estimators, config.RF_N_ESTIMATORS)
        self.assertEqual(model.random_state, config.RANDOM_SEED)
        for person in people:
            scored = scorer.score_events(events, person, {}, {})
            top_directions = {item.event.direction_key for item in scored[:3]}
            self.assertEqual(top_directions, person.directions)
            self.assertTrue(all(0 <= item.score <= 1 for item in scored))
        self.assertEqual(scorer.score_events([], people[0]), [])


class TrainingDatabaseTests(support.DatabaseCase):
    """Verify selection, user-specific chronology, sample weights and feedback persistence."""

    def setUp(self):
        """Create two profiles without any generated demo or real database access."""
        super().setUp()
        self.user = database.create_user(self.connection, 'Alex', now=support.NOW)
        self.synthetic = database.create_user(self.connection, 'Lena', is_synthetic=True,
                                               sharing_opt_in=True, now=support.NOW)
        for user_id in (self.user, self.synthetic):
            database.set_user_directions(self.connection, user_id, {'career'})

    def add_event(self, name, start, end=None):
        """Save one isolated occurrence and return its ID and interval."""
        end = end or start + timedelta(hours=1)
        self.save([support.record(external_id=name, start=start, end=end)], include_past=True)
        event_id = self.scalar('SELECT MAX(id) FROM events')
        return event_id, start, end

    def answer(self, event, user_id=None, status='attended', rating=None, demo=False):
        """Use the real state machine at valid fixed clocks, optionally marking a demo fixture."""
        event_id, start, end = event
        user_id = user_id or self.user
        database.save_interaction(self.connection, user_id, event_id, 'confirm',
                                  now=start - timedelta(days=1))
        if status != 'confirmed':
            now = start - timedelta(hours=1) if status == 'cancel' else end + timedelta(minutes=1)
            database.save_interaction(self.connection, user_id, event_id, status, now=now)
        if rating is not None:
            database.save_interaction(self.connection, user_id, event_id, 'rate', rating,
                                      now=end + timedelta(minutes=2))
        if demo:
            with self.connection:
                self.connection.execute('UPDATE interactions SET is_demo=1 WHERE user_id=? '
                                        'AND event_id=?', (user_id, event_id))

    def test_no_self_or_same_start_leakage_and_weights(self):
        """Use strictly earlier events, isolate users, and give genuine local rows weight five."""
        start = support.NOW - timedelta(days=4)
        first = self.add_event('first', start)
        peer = self.add_event('same-start', start)
        later = self.add_event('later', start + timedelta(days=1))
        self.answer(first, rating=5)
        self.answer(peer, rating=3, demo=True)
        self.answer(later, rating=1)
        self.answer(first, self.synthetic, rating=4)
        X, y, weights = recommender.build_training_data(self.connection, now=support.NOW)
        self.assertEqual(list(X['earlier_avg_rating_in_bundle']), [3, 3, 4, 3])
        self.assertEqual(list(y), [1, 0, 0, 1])
        self.assertEqual(list(weights), [5, 1, 5, 1])

    def test_only_available_attended_ratings_train(self):
        """Exclude confirmed, cancelled, no-show, unrated and future-answer examples."""
        start = support.NOW - timedelta(days=5)
        for index, state in enumerate(('confirmed', 'cancel', 'not_attended', 'attended')):
            event = self.add_event(str(index), start + timedelta(hours=index))
            self.answer(event, status=state)
        rated = self.add_event('rated', start + timedelta(days=1))
        self.answer(rated, rating=5)
        future_answer = self.add_event('late-answer', support.NOW - timedelta(minutes=90),
                                        end=support.NOW - timedelta(seconds=30))
        self.answer(future_answer, rating=1)
        X, y, weights = recommender.build_training_data(self.connection, now=support.NOW)
        self.assertEqual(len(X), 1)
        self.assertEqual(list(y), [1])
        averages = database.get_user_bundle_averages(self.connection, self.user, support.NOW)
        self.assertAlmostEqual(averages['career_tech'], 5)

    def test_pending_feedback_and_strict_end(self):
        """Return only this user's ended unanswered rows in chronological order."""
        oldest = self.add_event('oldest', support.NOW - timedelta(days=3))
        recent = self.add_event('recent', support.NOW - timedelta(days=1))
        exact = self.add_event('exact', support.NOW - timedelta(hours=1), support.NOW)
        self.answer(oldest, status='attended')
        self.answer(recent, status='confirmed')
        self.answer(exact, status='confirmed')
        pending = database.get_pending_feedback(self.connection, self.user, support.NOW)
        self.assertEqual(list(pending['event_id']), [oldest[0], recent[0]])
        database.save_interaction(self.connection, self.user, oldest[0], 'rate', 4, support.NOW)
        database.save_interaction(self.connection, self.user, recent[0], 'not_attended',
                                  now=support.NOW)
        pending = database.get_pending_feedback(self.connection, self.user, support.NOW)
        self.assertTrue(pending.empty)

    def test_rating_revision_handles_corrections_and_noops(self):
        """Change the cache token once per effective rating, including edits with the same count."""
        event = self.add_event('rating', support.NOW - timedelta(days=1))
        self.answer(event)
        self.assertEqual(database.get_rating_cache_key(self.connection), (0, 0))
        database.save_interaction(self.connection, self.user, event[0], 'rate', 4, support.NOW)
        self.assertEqual(database.get_rating_cache_key(self.connection), (1, 1))
        database.save_interaction(self.connection, self.user, event[0], 'rate', 4, support.NOW)
        self.assertEqual(database.get_rating_cache_key(self.connection), (1, 1))
        database.save_interaction(self.connection, self.user, event[0], 'rate', 2, support.NOW)
        self.assertEqual(database.get_rating_cache_key(self.connection), (1, 2))
        with self.assertRaises(ValueError):
            database.save_interaction(self.connection, self.user, event[0], 'rate', 0, support.NOW)
        self.assertEqual(database.get_rating_cache_key(self.connection), (1, 2))

    def test_demo_removal_preserves_real_and_other_user_feedback(self):
        """Delete only local demo rows and invalidate the model only if rated rows were removed."""
        first = self.add_event('demo', support.NOW - timedelta(days=3))
        second = self.add_event('real', support.NOW - timedelta(days=2))
        self.answer(first, rating=4, demo=True)
        self.answer(second, rating=5)
        self.answer(first, self.synthetic, rating=3)
        before = database.get_rating_cache_key(self.connection)
        self.assertEqual(database.clear_demo_history(self.connection, self.user), 1)
        self.assertEqual(database.get_rating_cache_key(self.connection), (2, before[1] + 1))
        self.assertIsNotNone(database.get_interaction(self.connection, self.user, second[0]))
        self.assertIsNotNone(database.get_interaction(self.connection, self.synthetic, first[0]))
        with self.assertRaises(ValueError):
            database.clear_demo_history(self.connection, self.synthetic)

    def test_friend_feature_respects_sharing(self):
        """Count opted-in friends, excluding private, cancelled or unrelated plans."""
        event = self.add_event('future', support.NOW + timedelta(days=1))
        self.answer(event, self.synthetic, status='confirmed')
        private = database.create_user(self.connection, 'Private', now=support.NOW)
        self.answer(event, private, status='confirmed')
        with self.connection:
            for friend_id in (self.synthetic, private):
                self.connection.execute('''INSERT INTO friendships (user_id,friend_id,created_at)
                    VALUES (?,?,?)''', (self.user, friend_id, database.to_db_text(support.NOW)))
        counts = friends.friends_going_counts(self.connection, self.user, {event[0]})
        self.assertEqual(counts, {event[0]: 1})
        database.save_interaction(self.connection, self.synthetic, event[0], 'cancel',
                                  now=support.NOW)
        self.assertEqual(friends.friends_going_counts(self.connection, self.user, {event[0]}), {})
